def minimize_inversions(N, K, S):
    count_zeros, inversion_count = 0, 0

    for s in S:
        if s == '1':
            inversion_count += count_zeros
            count_zeros = 0
        else:
            count_zeros += 1

        if (K - count_zeros) <= 0:
            break

    inversion_count += K * N // 2
    if K < N:
        count_zeros += 1
        inversion_count -= (K - count_zeros) * N // 2

    return inversion_count

