def find_array(n):
    from random import choice

    # Function to calculate the prestige of a chosen mode
    def calculate_prestige(mode, targets):
        prestige = 1
        counts = []
        for element in targets:
            counts.append(mode)
            target_count = counts.count(element)
            if target_count == element:
                prestige += 1
        return prestige, counts

