    def main():
        prestige = 1
        requested_prestige = 1
        targets = [choice(range(1, 10e9 + 1))]
        for i in range(n):
            while prestige < requested_prestige:
                prestige_down, targets = calculate_prestige(Counter(targets).most_common(), targets)
                prestige //= 2
                if prestige_down:
                    requested_prestige *= 3

        return choice(targets)

    # Check if the provided number's prestige fits the standard
    def is_elf_number(num):
        popularity = Counter(num).most_common()
        prestige, _ = calculate_prestige(popularity[0][0], [num] * len(popularity))
        return prestige == 1

