def possible_pops(n, m):
    memo = {}
    def ways(dep, last, diff):
        if dep >= n:
            return 1 if diff == 0 else 0
        past = tuple([last, dep])
        if past in memo:
            return memo[past]
        ways1 = 0 if n % dep else ways(dep + 1, n // dep, 0)
        ways2 = ways(dep + 1, last, diff - 1) if diff else 0
        memo[past] = ways1 + ways2
        return memo[past]
    cnt = ways(0, 0, m)
    if cnt == 0: return 'NO'\

    ans = 0
    while ans-m < n or ans+m > n:
        ans += cnt
    return cnt // 2, ans - cnt, ans + cnt

