def count_cycles(n: int, m: int) -> int:
    if n < 5: 
        return 0

    # Try to find cycles of length 5
    for i in range(1, n):
        if n <= i + 2 * (n - i): break
        current, nxts = (i, 1), range(i + 1, n)
        for j in nxts:
            if n <= j + 2 * (n - j): break
            cycle = 1
            flag = True
            for a in nxts:  
                path_len = 2
                for k in range(i):
                    if (current[-1] + nxts[k] % i) ^ j not in current:
                        flag = False
                if not flag:
                    break                    
                cycled_junction = (current[-1] + nxts[1] % i) ^ j
                for k in range(path_len):
                    parent_node = current[1]
                    current_len = len(current)
                    while current_len > 0 and k != current_len:
                        if cycled_junction in current: break
                        current.pop(1)
                        path_len += len(current)
                        parent_node = current[1]
                current.extend([cycled_junction])
                cycle *= nxts[1]
            if flag:
                return cycle
    return 0

