def calculate_dominance_probability(length, probabilities, start_index, end_index):
    return sum(min(p, 1 - continue_probability) for p in probabilities if p >= probabilities[start_index] - 1e-9)

class ProbabilityCalculator:
    def __init__(self, probabilities):
        self.length = len(probabilities)
        self.probabilities = probabilities[:]
        self.start_index = -1
        self.end_index = self.length + 1
        self.update_dominance_probability()

    def update_dominance_probability(self):
        # Sort probabilities for binary search
        self.probabilities.sort()
        self.end_index = self.length + 1
        while self.length > self.end_index > 0 and self.probabilities[self.end_index - 1] > self.end_index / 2:
            self.end_index -= 1
        if self.end_index <= 0:
            return
        while self.move_half() > 0:
            self.end_index -= 1

    def move_half(self):
        add = 0
        while add < self.length:
            i = bisect_left(self.probabilities, self.end_index / 2.0, lo=0, hi=add)
            if i < add:
                end_index = bisect_left(self.probabilities, self.end_index * (2.0 - self.end_index / (add + 1)), hi=add + 1)
            else:
                end_index = bisect_left(self.probabilities, self.end_index * (2.0 - self.end_index / i), hi=add + 1)
            if end_index - 1 <= self.length / 2:
                self.length = end_index
                self.end_index = self.length + 1
                self.update_dominance_probability()
                break
            add = end_index
        return add - self.length

