MOD = 998244353

def factMod(n):
    ans = 1
    for i in range(2, n + 1):
        ans = (ans * i) % MOD
    return ans

def inverseMod(a):
    b = a
    c = MOD
    while c > 0:
        q = a // c
        r = a % c
        a = c
        b = (b - q * a) % MOD
        c = r
    if b < 0:
        b += MOD
    return b

def primeFactorization(n):
    factors = []
    d = 2
    while n >= d * d:
        while n % d == 0:
            factors.append(d)
            n //= d
        if n == 1:
            break
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def factorialInverse(n):
    return inverseMod(factMod(n))

