# Function to check if a number is a perfect square
def is_square(n):
    if n < 0:
        return False
    root = int(n**0.5)
    return root * root == n

def numberOfGoodSubsets(n, arr_pairs):
    total_subsets = 1
    for i in range(n):
        different_parts = 0
        for j in range(1, 2 * n, 5):
            arr = set(arr_pairs[j])
            if len(arr) != 5:
                continue
            for arr_1 in arr:
                for arr_2 in arr:
                    if arr_pairs[j + 1][i] == arr_pairs[j + 2][i] and arr_pairs[j + 3][i] == arr_pairs[j + 4][i]:
                        if (arr_pairs[j + 2][i] - arr_pairs[j + 3][i])**2 % n == 0:
                            break
                else:
                    different_parts += 1                        
        different_parts = different_parts >> 1
        total_subsets = total_subsets * pow(primeFactorization(2 + len(arr)) + 1, different_parts, MOD) % MOD

    result = factMod(total_subsets)
    result = result * pow(factMod(n), MOD - 2, MOD) % MOD
    return result


