def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def merge_sort(arr, low, high, k):
    if low >= high:
        return (0, arr.copy())
    mid = (low + high) // 2
    left = merge_sort(arr, low, mid, k)
    right = merge_sort(arr, mid + 1, high, k)
    return left[0] + right[0], merge(arr, low, mid, high, k)

def merge(arr, low, mid, high, k):
    merge_cnt = 0
    inv_cnt, temp = 0, [0] * (high - low + 1)
    left_end = mid + 1
    for i in range(low, mid + 1):
        while left_end <= high and arr[i] > 2 * arr[left_end]:
            left_end += 1
        inv_cnt += (left_end - mid - 1)
        merge_cnt += (i + 1 - low) * (high - left_end + 1)
        merge_cnt += max(0, (left_end - 1) - mid - 1)
    for i in range(low, mid + 1):
        if merge_cnt and arr[i] == 0:
            merge_cnt -= 1
            continue
        while left_end <= high and arr[i] <= arr[left_end]:
            left_end += 1
        temp[high - low + i - low] = arr[left_end - 1]
    for i in range(low, mid + 1):
        left_end -= 1
        temp[low + i - low] = arr[i]
    for i in range(low, high + 1):
        arr[i] = temp[i - low]
    return inv_cnt, arr

def expected_inversions(n, k, q):
    arr = [i + 1 for i in range(n)]
    top = 2
    while top < q:
        if top % 2 == 1:
            merge_sort(arr, 0, n - 1, k)
        merge_cnt, arr = merge_sort(arr, 0, n - 1, k)
        inv = (n - 1) * k
        for i in range(n):
            inv += (arr[i] - i) * (arr[0] - 1)
        inv = inv // 2
        inv = (inv + inv and merge_cnt) // k
        top <<= 1
    return (inv % q) * q // k

