# We choose a diagonal sequence that crosses every row and column
def find_robot_instructions(R, C):
    # We assume the obstacle is in the top-left corner for simplicity
    obstacle_position = (1, 1)

    # Define the robot's paths
    def robot_path(instruction):
        if instruction == 'L':
            return lambda row: row - 1
        elif instruction == 'R':
            return lambda row: row + 1
        elif instruction == 'U':
            return lambda col: col - 1
        elif instruction == 'D':
            return lambda col: col + 1

    # Function to check if the obstacle can be found from the end position with given sequence
    def can_find_obstacle(final_row, final_col):
        for col in range(C):
            # Move left or right until we find the obstacle
            path = lambda row: row if final_col < C - row + 1 else robot_path('L')(row)
            for row in range(final_row - 1, -(final_row == 1) + 1):
                if path(row)(col) == border:
                    return True
        return False

    border = C
    path = robot_path('L')
    if any(can_find_obstacle(i, i) for i in range(1, R + 1)):
        for instruction in 'URDL':
            if any(can_find_obstacle(i, i) for i in range(1, R + 1)):
                return instruction
    return '!'  # Return error if no valid sequence found

