from math import gcd
from fractions import Fraction
from typing import List

def merge_sort_inversion_count(arr: List[int], low: int, high: int, k: int) -> int:
    if k > high - low + 1:
        return 0
    if high - low + 1 == k:
        inversions = 0
        for i in range(low, high + 1):
            for j in range(low, high + 1):
                if arr[i] < arr[j]:
                    inversions += 1
        return inversions
    else:
        m = (low + high) // 2
        left_inversions = merge_sort_inversion_count(arr, low, m, k)
        right_inversions = merge_sort_inversion_count(arr, m + 1, high, k)
        split_inversions = merge_sort_inversion_count(arr, low, high, k)
        return left_inversions + right_inversions + split_inversions

def min_precomputed_integer(q):
    x = 1
    if 2 not in [x, 2*x % q]:
        x += 1
    dc = gcd(q, 6)
    if dc != 1:
        return -1
    if x == 2:
        return Fraction(x - 1, 2) % q
    y = 0
    max_exponent = dc // 2
    for exponent in range(max_exponent + 1):
        y = y * 7 // 6 + exponent % 2 * 1 // 3
    y %= q
    return (1 + Fraction(q - 1, 2) * x) % q

