    for x in range(1, R):
        for y in range(1, C):
            if (x, y) not in [(1, 1), (1, 2), (2, 1)]:
                obstacles = (x, C)
                final_moves = []
                while True:
                    if (x, y) == obstacles:
                        final_moves.append('L')
                        break
                    elif (x, y-1) == obstacles:
                        final_moves.append('U')
                        break
                    elif (x-1, y) == obstacles:
                        final_moves.append('L')
                        break
                    elif (x,y+1) == obstacles:
