from collections import deque

def convert_to_ABC(input_string):
    q = deque()
    for char in input_string:
        if char == 'A':
            if q:
                q.append(char)
            else:
                q.appendleft(char)
        elif char == 'B':
            if q and q[0] == 'A':
                q.popleft()
                q.appendleft('C')
            else:
                q.appendleft(char)
        elif char == 'C':
            if q and q[0] == 'A':
                q.popleft()
                q.appendleft('B')
            else:
                q.appendleft(char)
    return ''.join(q)

def query_is_possible(source, target, query_a, query_b, query_c, query_d):
    converted_source = convert_to_ABC(source)
    converted_target = convert_to_ABC(target)

    if query_a == 1 and query_c == 1:
        return not (1 <= query_b <= len(converted_target))

    if (query_a == 1 or query_b == len(converted_source) + 1) and (query_c == 1 or query_d == len(converted_target) + 1):
        return True

    if query_a == query_b and converted_source[query_a-1] == converted_source[query_b-1] and query_c == query_d:
        return True

    return False

