import math

def count_tuples(N):
    count = 0

    # Iterate over all possible values of x, y, and z
    for x in range(1, N+1):
        for y in range(1, N+1):
            for z in range(1, N+1):
                for w in range(1, N+1):

                    # Check if (w/x) + (y/z) is an integer
                    if (w // x + y // z) == (w // x + y // z):
                        count += 1

    return count

